/* EPIC DEVICES service worker, generated by build.mjs.
   Pages: network first, so a new deploy shows at once; falls back to the saved copy offline.
   Code bundles and fonts: cache first (bundle names change with every build).
   Images: served from cache instantly and refreshed in the background. */
const VERSION = '__VERSION__';
const SHELL = 'epic-shell-' + VERSION;
const STATIC = 'epic-static-' + VERSION;
const IMAGES = 'epic-images-v1';
const SHELL_FILES = __SHELL__;

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(SHELL)
      .then((cache) => Promise.allSettled(SHELL_FILES.map((url) => cache.add(new Request(url, { cache: 'reload' })))))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((key) => key.startsWith('epic-') && ![SHELL, STATIC, IMAGES].includes(key)).map((key) => caches.delete(key))))
      .then(() => self.clients.claim()),
  );
});

const withTimeout = (promise, ms) => Promise.race([promise, new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), ms))]);

async function networkFirst(request) {
  const cache = await caches.open(SHELL);
  try {
    const response = await withTimeout(fetch(request), 4000);
    if (response.ok) cache.put(request, response.clone());
    return response;
  } catch {
    return (await cache.match(request, { ignoreSearch: true })) || (await cache.match('./index.html')) || Response.error();
  }
}

async function cacheFirst(request) {
  const cache = await caches.open(STATIC);
  const hit = await cache.match(request);
  if (hit) return hit;
  const response = await fetch(request);
  if (response.ok) cache.put(request, response.clone());
  return response;
}

async function trim(cache, max) {
  const keys = await cache.keys();
  for (let i = 0; i < keys.length - max; i += 1) await cache.delete(keys[i]);
}

async function staleWhileRevalidate(event) {
  const cache = await caches.open(IMAGES);
  const hit = await cache.match(event.request);
  const refresh = fetch(event.request)
    .then((response) => {
      if (response.ok) cache.put(event.request, response.clone()).then(() => trim(cache, 180));
      return response;
    })
    .catch(() => hit || Response.error());
  if (hit) {
    event.waitUntil(refresh.then(() => undefined));
    return hit;
  }
  return refresh;
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  if (request.mode === 'navigate') {
    event.respondWith(networkFirst(request));
  } else if (/\/assets\/(app|console)-[A-Z0-9]+\.js$/.test(url.pathname) || url.pathname.includes('/assets/fonts/')) {
    event.respondWith(cacheFirst(request));
  } else if (/\.(webp|avif|png|jpe?g|svg|ico)$/i.test(url.pathname)) {
    event.respondWith(staleWhileRevalidate(event));
  }
});
